#!/usr/bin/env bash
# tools/gen-persona-skills.sh — generates one loader skill per persona
# manifest, and removes stale auto-generated loader skills whose manifest
# disappeared. Two modes:
#
#   repo mode (default) — reads claude-config/context/personas/ in this repo,
#     writes claude-config/skills/persona-<group>-<persona>/SKILL.md. This is
#     the public, shared doctrine library.
#
#   --local mode — reads a PRIVATE library directory (mirrors the
#     ~/.claude/context-local/ overlay convention: <dir>/personas/<group>/
#     <persona>.md manifests, <dir>/skills/<category>/<slice>.md slices) and
#     writes into a caller-chosen --out directory. A --local manifest's slice
#     list may mix two kinds of entries:
#       - plain (e.g. "skills/foo/bar.md")   -> lives in the local dir itself
#       - "shared:skills/foo/bar.md"         -> lives in the SHARED library,
#         resolved against --shared-root (required alongside --local)
#
# Why: agent definitions can't @import a persona manifest directly (@import
# only expands inside the CLAUDE.md/rules-file chain, never inside an agent
# definition body — see claude-config/context/README.md "Dual consumption").
# This script bridges that gap by emitting a `persona-<group>-<persona>`
# loader skill per manifest, in the same `!`bash .../resolve-slices.sh ...``
# live-load shape already used by the roster-sdm / roster-sde / liveliness
# loader skills. Agents then list the generated skill name in their own
# frontmatter `skills:` list.
#
# Overlay-aware loader body (BOTH modes): every slice a generated skill loads
# is resolved at INVOCATION time (not generation time) by ONE call to the
# shared helper script, claude-config/context/resolve-slices.sh, which checks
# each argument's local-overlay copy (~/.claude/context-local/<path>) first
# and falls back to the shared copy (~/.claude/context/<path>) — a private
# override always wins, and a missing slice warns to stderr instead of
# failing the whole load:
#
#   !`bash ~/.claude/context/resolve-slices.sh <slice1> <slice2> ...`
#
# This is a deliberate simplification from an earlier version that inlined
# the local-wins/shared-fallback logic as a `for`/`if` shell loop directly in
# the loader line: that inline shell-expansion pattern is not something
# Claude Code's Bash permission allowlist matcher can safely auto-approve
# under default permission mode, so the loader silently failed to inject. One
# helper-script call is a single, allowlistable command instead.
#
# Both modes emit the SAME loader-body shape — one resolve-slices.sh call
# over the manifest's slice paths, in order, with any "shared:" prefix
# stripped (resolve-slices.sh has no notion of that prefix; it just does
# local-first/shared-fallback per path). --local mode's plain entries only
# ever live under ~/.claude/context-local/, so the helper's local-first check
# is exactly the resolution they need (there is no shared copy at that path
# to fall back to). Only the frontmatter description/marker and the body's
# framing header still differ per mode.
#
# What it reads (repo mode):
#   <root>/claude-config/context/personas/<group>/<persona>.md
# What it reads (--local mode):
#   <local-dir>/personas/<group>/<persona>.md
#     ---
#     persona: <name>
#     group: <group>
#     description: <one line>
#     slices:
#       - skills/<category>/<slice>.md          # local dir, both modes
#       - shared:skills/<category>/<slice>.md   # shared root, --local only
#     ---
#     # Persona: <group>/<persona>
#     <prose + @ lines — ignored; only the frontmatter above matters>
#
# What it writes:
#   repo mode:    <root>/claude-config/skills/persona-<group>-<persona>/SKILL.md
#   --local mode: <--out dir>/persona-<group>-<persona>/SKILL.md
#
# Validation (any violation aborts the WHOLE run before anything is written —
# a bad manifest never produces a partial output set):
#   - every listed slice path must exist (repo mode: under claude-config/
#     context/; --local mode: plain under --local dir, shared: entries under
#     --shared-root)
#   - every slice path (after stripping any "shared:" prefix) must start with
#     `skills/`
#   - `persona` and `group` must be kebab-case
#   - two manifests may not resolve to the same `persona-<group>-<persona>` name
#   - --local mode requires both --out and --shared-root; missing either is
#     an error (exit 2, before any manifest is even read)
#   - --local mode: if the target SKILL.md for a name already exists and does
#     NOT carry the local-generated marker (i.e. it's shared-generated or
#     hand-written), that's a COLLISION — the run errors instead of
#     overwriting it
#
# Stale cleanup: any existing persona-*/ directory whose SKILL.md contains
# THIS RUN's marker but has no corresponding manifest anymore is deleted.
#   - repo mode matches the shared marker ("AUTO-GENERATED by ...")
#   - --local mode matches the local marker ("AUTO-GENERATED (local)") only —
#     a shared-generated or hand-written persona-* skill is NEVER a stale-
#     cleanup candidate in --local mode, even when no local manifest names it
#   - a hand-written skill directory that happens to be named `persona-*` but
#     lacks the relevant marker is NEVER touched by either mode
#
# Root resolution: script-directory based (this script lives in tools/, so
# its parent is the repo root), overridable via the GEN_PERSONA_ROOT env var
# — the seam the test suite uses to point the generator at a throwaway
# fixture tree instead of the real repo. Only used by repo mode (and as the
# base for the default claude-config/skills output dir); --local mode takes
# all its paths from --local/--out/--shared-root instead.
#
# Usage:
#   tools/gen-persona-skills.sh
#       generate/update/prune the repo's shared personas in place
#   tools/gen-persona-skills.sh --check
#       report only; exit 1 if anything would change, 0 if already in sync
#   tools/gen-persona-skills.sh --local <dir> --out <dir> --shared-root <dir> [--check]
#       generate/update/prune a private persona library
#   tools/gen-persona-skills.sh --help
#       show this usage
#
# Graceful no-op: if the personas directory doesn't exist, or exists but has
# no manifests, this prints a message and exits 0 without touching anything
# else (including stale cleanup) — this is the real repo's state until the
# first persona manifest ships.
set -euo pipefail

usage() {
  sed -n '2,/^set -euo pipefail/p' "$0" | sed '$d'
}

CHECK=0
LOCAL_MODE=0
LOCAL_DIR=""
OUT_DIR=""
SHARED_ROOT=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --check)
      CHECK=1
      shift
      ;;
    --local)
      if [[ $# -lt 2 ]]; then
        printf -- '--local requires a directory argument\n' >&2
        exit 2
      fi
      LOCAL_MODE=1
      LOCAL_DIR="$2"
      shift 2
      ;;
    --out)
      if [[ $# -lt 2 ]]; then
        printf -- '--out requires a directory argument\n' >&2
        exit 2
      fi
      OUT_DIR="$2"
      shift 2
      ;;
    --shared-root)
      if [[ $# -lt 2 ]]; then
        printf -- '--shared-root requires a directory argument\n' >&2
        exit 2
      fi
      SHARED_ROOT="$2"
      shift 2
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      printf 'Unknown argument: %s\n' "$1" >&2
      usage >&2
      exit 2
      ;;
  esac
done

if [[ $LOCAL_MODE -eq 1 ]]; then
  if [[ -z "$OUT_DIR" ]]; then
    printf 'ERROR: --out is required when --local is given\n' >&2
    exit 2
  fi
  if [[ -z "$SHARED_ROOT" ]]; then
    printf 'ERROR: --shared-root is required when --local is given\n' >&2
    exit 2
  fi
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="${GEN_PERSONA_ROOT:-$(cd "$SCRIPT_DIR/.." && pwd)}"

CONTEXT_DIR="$ROOT/claude-config/context"

if [[ $LOCAL_MODE -eq 1 ]]; then
  PERSONAS_DIR="$LOCAL_DIR/personas"
  SKILLS_DIR="$OUT_DIR"
else
  PERSONAS_DIR="$CONTEXT_DIR/personas"
  SKILLS_DIR="$ROOT/claude-config/skills"
fi

MARKER="AUTO-GENERATED by tools/gen-persona-skills.sh"
MARKER_LOCAL="AUTO-GENERATED (local)"
KEBAB_RE='^[a-z0-9]+(-[a-z0-9]+)*$'

# trim <string> — strip leading/trailing whitespace.
trim() {
  local s="$1"
  s="${s#"${s%%[![:space:]]*}"}"
  s="${s%"${s##*[![:space:]]}"}"
  printf '%s' "$s"
}

# parse_manifest <file> — sets globals MF_PERSONA, MF_GROUP, MF_DESCRIPTION,
# MF_SLICES (array). Only the first frontmatter block (between the first two
# `---` lines) is read; the body is never scanned.
parse_manifest() {
  local file="$1"
  MF_PERSONA=""
  MF_GROUP=""
  MF_DESCRIPTION=""
  MF_SLICES=()

  local in_fm=0 in_slices=0 line
  while IFS= read -r line || [[ -n "$line" ]]; do
    if [[ "$line" == "---" ]]; then
      if [[ $in_fm -eq 0 ]]; then
        in_fm=1
        continue
      else
        break
      fi
    fi
    [[ $in_fm -eq 0 ]] && continue

    if [[ "$line" =~ ^persona:[[:space:]]*(.*)$ ]]; then
      MF_PERSONA="$(trim "${BASH_REMATCH[1]}")"
      in_slices=0
      continue
    fi
    if [[ "$line" =~ ^group:[[:space:]]*(.*)$ ]]; then
      MF_GROUP="$(trim "${BASH_REMATCH[1]}")"
      in_slices=0
      continue
    fi
    if [[ "$line" =~ ^description:[[:space:]]*(.*)$ ]]; then
      MF_DESCRIPTION="$(trim "${BASH_REMATCH[1]}")"
      in_slices=0
      continue
    fi
    if [[ "$line" =~ ^slices:[[:space:]]*$ ]]; then
      in_slices=1
      continue
    fi
    if [[ $in_slices -eq 1 && "$line" =~ ^[[:space:]]+-[[:space:]]*(.+)$ ]]; then
      MF_SLICES+=("$(trim "${BASH_REMATCH[1]}")")
      continue
    fi
    in_slices=0
  done < "$file"
}

# validate_manifest <file> — validates the globals parse_manifest just set.
# Prints one ERROR line per problem to stderr; returns nonzero if any found.
# Slice resolution depends on mode: repo mode resolves every slice against
# CONTEXT_DIR; --local mode resolves plain entries against LOCAL_DIR and
# "shared:"-prefixed entries (prefix stripped) against SHARED_ROOT.
validate_manifest() {
  local file="$1" ok=1

  if [[ -z "$MF_PERSONA" ]]; then
    printf 'ERROR: %s: missing persona\n' "$file" >&2
    ok=0
  elif [[ ! "$MF_PERSONA" =~ $KEBAB_RE ]]; then
    printf 'ERROR: %s: persona "%s" is not kebab-case\n' "$file" "$MF_PERSONA" >&2
    ok=0
  fi

  if [[ -z "$MF_GROUP" ]]; then
    printf 'ERROR: %s: missing group\n' "$file" >&2
    ok=0
  elif [[ ! "$MF_GROUP" =~ $KEBAB_RE ]]; then
    printf 'ERROR: %s: group "%s" is not kebab-case\n' "$file" "$MF_GROUP" >&2
    ok=0
  fi

  if [[ -z "$MF_DESCRIPTION" ]]; then
    printf 'ERROR: %s: missing description\n' "$file" >&2
    ok=0
  fi

  if (( ${#MF_SLICES[@]} == 0 )); then
    printf 'ERROR: %s: no slices listed\n' "$file" >&2
    ok=0
  else
    local s path_part base_dir label
    for s in "${MF_SLICES[@]}"; do
      if [[ $LOCAL_MODE -eq 1 && "$s" == shared:* ]]; then
        path_part="${s#shared:}"
        base_dir="$SHARED_ROOT"
        label="shared root ($SHARED_ROOT)"
      elif [[ $LOCAL_MODE -eq 1 ]]; then
        path_part="$s"
        base_dir="$LOCAL_DIR"
        label="local dir ($LOCAL_DIR)"
      else
        path_part="$s"
        base_dir="$CONTEXT_DIR"
        label="$CONTEXT_DIR"
      fi

      if [[ "$path_part" != skills/* ]]; then
        printf 'ERROR: %s: slice "%s" does not start with skills/\n' "$file" "$s" >&2
        ok=0
        continue
      fi
      if [[ ! -f "$base_dir/$path_part" ]]; then
        printf 'ERROR: %s: slice "%s" does not exist under %s\n' "$file" "$s" "$label" >&2
        ok=0
      fi
    done
  fi

  [[ $ok -eq 1 ]]
}

# render_skill <group> <persona> <description> <slice1> [slice2 ...] —
# prints the exact SKILL.md content for one persona loader. Both modes emit
# the SAME loader-body shape (a single resolve-slices.sh call); only the
# frontmatter marker and the framing header differ per mode. Any "shared:"
# prefix is stripped from each slice before it's passed to the helper —
# resolve-slices.sh itself has no notion of that prefix, it just does
# local-overlay-wins/shared-fallback per plain path (see
# claude-config/context/resolve-slices.sh).
render_skill() {
  local group="$1" persona="$2" description="$3"
  shift 3
  local s stripped_slices=()
  for s in "$@"; do
    stripped_slices+=("${s#shared:}")
  done
  local slices="${stripped_slices[*]}"

  local marker header
  if [[ $LOCAL_MODE -eq 1 ]]; then
    marker="(AUTO-GENERATED (local) by tools/gen-persona-skills.sh --local — edit the manifest/slices and regenerate; do not hand-edit)"
    header="# Persona: ${group}/${persona} (local library; shared: slices resolve via the shared library overlay)"
  else
    marker="(AUTO-GENERATED by tools/gen-persona-skills.sh — edit the manifest/slices and regenerate; do not hand-edit)"
    header="# Persona: ${group}/${persona} (live from ~/.claude/context/, local overlay wins)"
  fi

  cat <<EOF
---
name: persona-${group}-${persona}
description: Persona loader — ${group}/${persona}: ${description} ${marker}
---
${header}

!\`bash ~/.claude/context/resolve-slices.sh ${slices}\`
EOF
}

# ---------------------------------------------------------------------------
# Discover manifests
# ---------------------------------------------------------------------------
if [[ ! -d "$PERSONAS_DIR" ]]; then
  echo "No persona manifests directory at $PERSONAS_DIR — nothing to do."
  exit 0
fi

manifests=()
while IFS= read -r -d '' f; do
  manifests+=("$f")
done < <(find "$PERSONAS_DIR" -mindepth 2 -maxdepth 2 -type f -name '*.md' -print0 | sort -z)

if (( ${#manifests[@]} == 0 )); then
  echo "No persona manifests found under $PERSONAS_DIR — nothing to do."
  exit 0
fi

# ---------------------------------------------------------------------------
# Parse + validate ALL manifests before writing anything. Any violation in
# ANY manifest aborts the whole run — no partial output.
# ---------------------------------------------------------------------------
M_FILE=() M_GROUP=() M_PERSONA=() M_DESC=()
# Slices are stored per-manifest as a newline-joined string (bash arrays
# can't hold arrays-of-arrays, and bash strings can't hold embedded NULs —
# newline is safe since a slice path is always a single YAML scalar line);
# decoded back into a real array with `mapfile` when rendering.
M_SLICES_JOINED=()

any_error=0
for mf in "${manifests[@]}"; do
  parse_manifest "$mf"
  if ! validate_manifest "$mf"; then
    any_error=1
    continue
  fi
  M_FILE+=("$mf")
  M_GROUP+=("$MF_GROUP")
  M_PERSONA+=("$MF_PERSONA")
  M_DESC+=("$MF_DESCRIPTION")
  M_SLICES_JOINED+=("$(printf '%s\n' "${MF_SLICES[@]}")")
done

# Duplicate persona-<group>-<persona> output names across manifests.
if (( ${#M_FILE[@]} > 0 )); then
  for ((i = 0; i < ${#M_FILE[@]}; i++)); do
    for ((j = i + 1; j < ${#M_FILE[@]}; j++)); do
      if [[ "${M_GROUP[i]}" == "${M_GROUP[j]}" && "${M_PERSONA[i]}" == "${M_PERSONA[j]}" ]]; then
        printf 'ERROR: %s and %s both resolve to persona-%s-%s — group+persona must be unique\n' \
          "${M_FILE[i]}" "${M_FILE[j]}" "${M_GROUP[i]}" "${M_PERSONA[i]}" >&2
        any_error=1
      fi
    done
  done
fi

if [[ $any_error -eq 1 ]]; then
  exit 1
fi

# ---------------------------------------------------------------------------
# Compute the desired state (name -> content), diffed against what's on disk.
# --local mode additionally guards against silently overwriting a shared-
# generated or hand-written skill that happens to share the target name —
# that's a collision, and it aborts the whole run instead of overwriting.
# ---------------------------------------------------------------------------
declare -A CONTENT
EXPECTED_NAMES=()
CREATED=() UPDATED=() UNCHANGED=()

collision_error=0
for ((i = 0; i < ${#M_FILE[@]}; i++)); do
  mapfile -t slices <<< "${M_SLICES_JOINED[i]}"

  name="persona-${M_GROUP[i]}-${M_PERSONA[i]}"
  content="$(render_skill "${M_GROUP[i]}" "${M_PERSONA[i]}" "${M_DESC[i]}" "${slices[@]}")"
  CONTENT["$name"]="$content"
  EXPECTED_NAMES+=("$name")

  target="$SKILLS_DIR/$name/SKILL.md"
  if [[ -f "$target" ]]; then
    existing="$(cat "$target")"
    if [[ $LOCAL_MODE -eq 1 && "$existing" != *"$MARKER_LOCAL"* ]]; then
      printf 'ERROR: %s already exists at %s and is not local-generated (missing "%s" marker) — refusing to overwrite a shared or hand-written skill\n' \
        "$name" "$target" "$MARKER_LOCAL" >&2
      collision_error=1
      continue
    fi
    if [[ "$existing" == "$content" ]]; then
      UNCHANGED+=("$name")
    else
      UPDATED+=("$name")
    fi
  else
    CREATED+=("$name")
  fi
done

if [[ $collision_error -eq 1 ]]; then
  exit 1
fi

# ---------------------------------------------------------------------------
# Stale cleanup candidates: existing persona-* dirs carrying THIS RUN's
# marker with no manifest producing them anymore. repo mode only ever
# considers shared-marked skills; --local mode only ever considers
# local-marked skills — so a --local run never deletes a shared-generated
# (or hand-written) persona-* skill, even when no local manifest names it.
# ---------------------------------------------------------------------------
DELETED=()
if [[ -d "$SKILLS_DIR" ]]; then
  is_expected() {
    local want="$1" n
    for n in "${EXPECTED_NAMES[@]}"; do
      [[ "$n" == "$want" ]] && return 0
    done
    return 1
  }

  if [[ $LOCAL_MODE -eq 1 ]]; then
    cleanup_marker="$MARKER_LOCAL"
  else
    cleanup_marker="$MARKER"
  fi

  while IFS= read -r -d '' d; do
    base="$(basename "$d")"
    [[ "$base" == persona-* ]] || continue
    smd="$d/SKILL.md"
    [[ -f "$smd" ]] || continue
    grep -qF "$cleanup_marker" "$smd" || continue
    is_expected "$base" && continue
    DELETED+=("$base")
  done < <(find "$SKILLS_DIR" -mindepth 1 -maxdepth 1 -type d -print0 | sort -z)
fi

# ---------------------------------------------------------------------------
# Report / apply
# ---------------------------------------------------------------------------
if [[ $CHECK -eq 1 ]]; then
  changes=$(( ${#CREATED[@]} + ${#UPDATED[@]} + ${#DELETED[@]} ))
  if (( changes == 0 )); then
    echo "up to date"
    exit 0
  fi
  for n in "${CREATED[@]}"; do echo "would create: $n"; done
  for n in "${UPDATED[@]}"; do echo "would update: $n"; done
  for n in "${DELETED[@]}"; do echo "would delete: $n"; done
  exit 1
fi

for n in "${CREATED[@]}"; do
  mkdir -p "$SKILLS_DIR/$n"
  printf '%s\n' "${CONTENT[$n]}" > "$SKILLS_DIR/$n/SKILL.md"
  echo "created: $n"
done
for n in "${UPDATED[@]}"; do
  mkdir -p "$SKILLS_DIR/$n"
  printf '%s\n' "${CONTENT[$n]}" > "$SKILLS_DIR/$n/SKILL.md"
  echo "updated: $n"
done
for n in "${DELETED[@]}"; do
  rm -rf -- "${SKILLS_DIR:?}/$n"
  echo "deleted (stale): $n"
done

if (( ${#CREATED[@]} == 0 && ${#UPDATED[@]} == 0 && ${#DELETED[@]} == 0 )); then
  echo "up to date"
fi

exit 0
